  "p.cutover.lede":
    "किसी सुरक्षा-क्रांतिक प्रणाली के कटओवर का निर्णय। रोक मानदंड पहले लिखे और प्रकाशित किए जाते हैं, फिर स्थिर कर दिए जाते हैं: उन्हें बदलने से नया संस्करण बनता है। गो के लिए हर मानदंड का पूरा होना और हर आवश्यक सह-हस्ताक्षर ज़रूरी है। नो-गो, या सुरक्षा के लिए विलंब, मानदंडों पर लिया गया निर्णय है; यह विलंब की चूक नहीं है।",
