  "p.ledger.nav": "वित्त-पोषण बही",
  "p.ledger.title": "वित्त-पोषण बही — PPM",
  "p.ledger.h1": "वित्त-पोषण बही",
  "p.ledger.lede":
    "प्रत्येक वित्त-पोषण आवंटन, उससे राशि लेने वाली बजट पंक्तियों, उनके गेट, पूरे हुए मील के पत्थरों और सत्यापित लाभों तक अनुरेखित। आवंटित परंतु आपके द्वारा पढ़ी जा सकने वाली किसी पंक्ति पर नियोजित न किया गया धन अननुरेखित है, और उसकी राशि के साथ दिखाया जाता है।",
  "p.ledger.scope":
    "आवंटन बनाना, लागत कोड मैप करना और वित्त निर्यात का मिलान API के माध्यम से किया जाता है; यह स्क्रीन बही पढ़ती है।",
