  "p.organizations.h1": "साझेदार संगठन",
  "p.organizations.lede":
    "वे संगठन जो पोर्टफ़ोलियो पर डिलीवरी, प्रायोजन, आपूर्ति या साझेदारी करते हैं। कोई पैक किसी संगठन को संबोधित किया जा सकता है, किसी मील के पत्थर को उसके अनुमोदन की आवश्यकता हो सकती है, और वह क्षमता प्रतिबद्ध कर सकता है। किसी संगठन को सेवानिवृत्त करने पर उसका इतिहास बना रहता है।",
