  "p.email_deliveries.lede":
    "हर ईमेल जिसे सेवा ने भेजने का प्रयास किया, प्रत्येक प्राप्तकर्ता के लिए एक पंक्ति: क्या वह भेजा गया, पुनः प्रयास की प्रतीक्षा में है, या स्थायी रूप से विफल हुआ, कितने प्रयास हुए, और अंतिम त्रुटि। इसे केवल व्यवस्थापक पढ़ सकते हैं, क्योंकि इसमें ईमेल पते हैं।",
