  "p.balance.rules":
    "चिह्न तब लगता है जब किसी पोर्टफ़ोलियो के पास नियोजित लागत या खुले जोखिम का {concentration}% या अधिक हो (कम से कम दो पोर्टफ़ोलियो होने पर), जब नियोजित लागत या जोखिम में उसका हिस्सा लक्षित मूल्य में उसके हिस्से से {gap} प्रतिशत अंक या अधिक हो, या जब उसकी नियोजित लागत हो पर चुनी गई मुद्रा में कोई लक्षित मूल्य न हो। चिह्न देखने का संकेत है, निर्णय नहीं।",
