  "p.balance.notes":
    "पोर्टफ़ोलियो के अनुसार समूहित, श्रेणी या रणनीतिक लक्ष्य के अनुसार नहीं: पोर्टफ़ोलियो ही एकमात्र समूहन है जिसके अनुसार लागत, लाभ मूल्य और जोखिम तीनों रिपोर्ट किए जाते हैं। लागत बजट पंक्तियों पर नियोजित राशि है, मूल्य दर्ज लाभों का लक्ष्य है, और जोखिम खुला एक्सपोज़र स्कोर है; विभिन्न मुद्राओं की राशियाँ कभी एक साथ नहीं जोड़ी जातीं।",
  "p.roadmap.title": "रोडमैप — प्रभाव, प्रयास और अभी / अगला / बाद में",
  "p.roadmap.h1": "रोडमैप: प्रभाव, प्रयास और अभी / अगला / बाद में",
  "p.roadmap.lede":
    "खुले विचार और निर्णयाधीन प्रस्ताव, इस आधार पर रखे गए कि वे कितने महत्वपूर्ण हैं (प्रभाव) और उनमें कितना काम लगेगा (प्रयास)। सेवा किसी विचार या प्रस्ताव का प्रभाव या प्रयास नहीं रखती, इसलिए आप यहाँ प्रत्येक का मूल्यांकन करते हैं; आपके मूल्यांकन केवल इसी ब्राउज़र में रखे जाते हैं और न साझा किए जाते हैं न सेवा को भेजे जाते हैं। दोनों मूल्यांकन के बिना कोई मद नहीं रखा जाता।",
  "p.roadmap.loading": "विचार और प्रस्ताव लोड हो रहे हैं…",
